contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 maker, uint256 taker) public {
        // avoid overflow when incrementing taker
        require(taker < type(uint256).max - 1);

        Fixed18 memory rateLower = c.rate(Position(maker, taker));
        Fixed18 memory rateHigher = c.rate(Position(maker, taker + 1));

        // utilization = taker/maker is non-decreasing in taker for fixed maker
        // (when maker == 0, unsafeDiv returns a constant, so rate is equal),
        // and the jump-rate curve is non-decreasing in utilization.
        assert(rateHigher.gte(rateLower));
    }
}

