contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public {
        bool reverted;
        try c.closeTakeFor(address(this), UFixed18.wrap(amount)) { reverted = false; } catch { reverted = true; }
        // The product is uninitialized (latestVersion() == 0, no positions), so the close
        // path (settle via the unset oracle/controller plus over-close protection) must
        // revert for every amount; a faulty contract could let a phantom close succeed.
        assert(reverted && c.latestVersion() == 0 && c.position(address(this)).maker == UFixed18.wrap(0) && c.position(address(this)).taker == UFixed18.wrap(0));
    }
    receive() external payable {}
}

