    constructor(C _c) { c = _c; }
    function run(address account, uint256 amount) public payable {
        require(account != address(this), "account must differ from caller");
        bool reverted;
        try c.closeTakeFor(account, UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
    receive() external payable {}
}

