contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address account) public {
        Position memory p = c.position(account);
        PrePosition memory pp = c.pre(account);
        assert(
            UFixed18.unwrap(p.maker) == 0 &&
            UFixed18.unwrap(p.taker) == 0 &&
            UFixed18.unwrap(pp.openPosition.maker) == 0 &&
            UFixed18.unwrap(pp.openPosition.taker) == 0 &&
            UFixed18.unwrap(pp.closePosition.maker) == 0 &&
            UFixed18.unwrap(pp.closePosition.taker) == 0 &&
            pp.oracleVersion == 0
        );
    }
    receive() external payable {}
}

